// Ejectable Field wrapper mapped to host primitives.
'use client'
import * as React from 'react'
import { Label } from '@/components/ui/label'
export function Field({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={['grid gap-2', className].filter(Boolean).join(' ')} {...props} />
}
export function FieldControl(props: React.HTMLAttributes<HTMLDivElement>) {
  return <div {...props} />
}
export function FieldDescription(props: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className='text-sm text-muted-foreground' {...props} />
}
export function FieldMessage({ children, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  if (!children) return null
  return <p className='text-sm text-destructive' {...props}>{children}</p>
}
export { Label }

'use client'
import * as React from 'react'
export function InputGroup({ className, ...props }: React.ComponentProps<'div'>) {
  return <div role='group' className={['group/input-group border-input relative flex w-full items-center rounded-md border shadow-xs h-9 min-w-0', className].filter(Boolean).join(' ')} {...props} />
}
export function InputGroupAddon({ className, align = 'inline-start', ...props }: React.ComponentProps<'div'> & { align?: 'inline-start'|'inline-end'|'block-start'|'block-end' }) {
  const alignCls = align==='inline-end'?'order-last pr-3': align==='block-start'?'order-first w-full justify-start px-3 pt-3': align==='block-end'?'order-last w-full justify-start px-3 pb-3':'order-first pl-3'
  return <div role='group' data-align={align} className={['text-muted-foreground flex h-auto items-center gap-2 py-1.5 text-sm', alignCls, className].filter(Boolean).join(' ')} {...props} />
}
export function InputGroupButton(props: React.ComponentProps<'button'>) {
  return <button type='button' className='px-2 py-1 text-sm' {...props} />
}
export function InputGroupText(props: React.ComponentProps<'span'>) {
  return <span className='text-muted-foreground flex items-center text-sm' {...props} />
}
export function InputGroupInput(props: React.ComponentProps<'input'>) {
  return <input className='flex-1 rounded-none border-0 bg-transparent shadow-none focus-visible:outline-none' {...props} />
}
export function InputGroupTextarea(props: React.ComponentProps<'textarea'>) {
  return <textarea className='flex-1 resize-none rounded-none border-0 bg-transparent py-3 shadow-none focus-visible:outline-none' {...props} />
}
